int main(void){assert(target_button47a(8)==-1&&target_button47a(16)==1&&target_button47a(64)==0&&target_button47a(0)==2);Combat g;combat_init(&g,1500,1500,NULL,NULL);g.apples=g.clover=g.jellopy=0;memset(g.extraItems,0,sizeof(g.extraItems));WindowUI u={0};assert(!ui_owned_count47(&g)&&ui_owned_item47(&g,0)==-1);ui_open(&u,UI_ITEMS,1);ui_input(&u,&g,2);assert(!u.active);inventory_add(&g,ITEM_RED_POTION,1);inventory_add(&g,ITEM_KNIFE,1);inventory_add(&g,ITEM_APPLE,1);assert(ui_owned_count47(&g)==3&&ui_owned_item47(&g,1)==ITEM_RED_POTION&&ui_owned_item47(&g,2)==ITEM_KNIFE);ui_open(&u,UI_ITEMS,1);u.choice[1]=2;ui_input(&u,&g,8);assert(inventory_equipped46(&g,ITEM_KNIFE));u.choice[1]=1;g.hp=1;ui_input(&u,&g,8);assert(!inventory_count(&g,ITEM_RED_POTION)&&ui_owned_count47(&g)==2);ui_tick(&u,&g,0);assert(ui_owned_item47(&g,1)==ITEM_KNIFE);u.choice[1]=0;ui_input(&u,&g,2);assert(u.placing&&u.carried==BIND_ITEM_BASE50+ITEM_APPLE);memset(g.mobs,0,sizeof(g.mobs));for(int i=0;i<4;i++){CombatMob*m=&g.mobs[i];m->enabled=1;m->hp=100;m->x=1510+i*20;m->y=1500;}g.mobs[3].aggro=1;g.target=-1;target_select47(&g,0,0,.8f,1);assert(g.target==0);for(int i=1;i<4;i++){target_select47(&g,1,0,.8f,1);assert(g.target==i);}target_select47(&g,1,0,.8f,1);assert(g.target==3);target_select47(&g,-1,0,.8f,1);assert(g.target==2);target_select47(&g,0,0,.8f,1);assert(g.target==0);g.mobs[0].hidden=1;target_select47(&g,0,0,.8f,1);assert(g.target==1);g.mobs[3].x=1900;assert(combat_valid_target(&g,3));assert(!target_visible47(&g,3,0,.8f,1));puts("PASS47 owned-only inventory, stable IDs for equipment/use/binding, depleted stacks, nearest/outward/inward targeting, no wrap, hidden and screen filtering.");}
